function f = HS26_f(x)
f = (x(1) - x(2)).^2 + (x(2) - x(3)).^4;
end

function g = HS26_g(x)
g = zeros(3, 1);
g(1) = 2*x(1) - 2*x(2);
g(2) = -2*x(1) + 2*x(2) + 4*(x(2) - x(3)).^3;
g(3) = -4*(x(2) - x(3)).^3;
end

function c = HS26_c(x)
c = zeros(1, 1);
c(1) = x(1).*(x(2).^2 + 1) + x(3).^4 - 3;
end

function J = HS26_J(x)
J = zeros(1, 3);
J(1, 1) = x(2).^2 + 1;
J(1, 2) = 2*x(1).*x(2);
J(1, 3) = 4*x(3).^3;
end
